import sys

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    p = 1
    children = [{}]
    top = [[]]
    cnt = {}
    out = []
    for _ in range(q):
        op = data[p]
        s = data[p + 1]
        p += 2
        if op == 'search':
            cnt[s] = cnt.get(s, 0) + 1
            node = 0
            for ch in s:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children.append({})
                    top.append([])
                    children[node][ch] = nxt
                node = nxt
                t = top[node]
                if s not in t:
                    t.append(s)
                t.sort(key=lambda u: (-cnt[u], u))
                if len(t) > 3:
                    t.pop()
        else:
            node = 0
            for ch in s:
                node = children[node].get(ch)
                if node is None:
                    break
            if node is None or not top[node]:
                out.append('-')
            else:
                out.append(' '.join(top[node]))
    print('\n'.join(out))

main()

