def gen(rng):
    def fmt(ops):
        return '\n'.join([str(len(ops))] + ['%s %s' % o for o in ops])
    tests = [
        fmt([('suggest', 'a')]),
        fmt([('search', 'a'), ('suggest', 'a'), ('suggest', 'ab'), ('suggest', 'b')]),
        fmt([('search', 'example.com/docs'), ('search', 'example.com/blog'), ('search', 'example.com/docs'),
             ('search', 'example.org'), ('suggest', 'example.com'), ('suggest', 'example'),
             ('suggest', 'ex.'), ('suggest', 'example.com/b')]),
        fmt([('search', 'a.io/x'), ('search', 'a.io/y'), ('search', 'a.io/z'), ('search', 'a.io/w'),
             ('search', 'a.io/z'), ('suggest', 'a.io/'), ('suggest', 'a.io/w')]),
        fmt([('search', 'ab'), ('search', 'abc'), ('search', 'abcd'), ('search', 'abcde'), ('search', 'abcde'),
             ('suggest', 'ab'), ('suggest', 'abcd'), ('suggest', 'abcde'), ('suggest', 'abcdef')]),
    ]
    alpha = 'ab./:'
    def rurl(maxlen, a=alpha):
        return ''.join(rng.choice(a) for _ in range(rng.randint(1, maxlen)))
    for n in (4, 8, 12, 20, 30, 40):
        for _ in range(3):
            pool = [rurl(5) for _ in range(rng.randint(2, 8))]
            ops = []
            for _ in range(n):
                if rng.random() < 0.5:
                    ops.append(('search', rng.choice(pool)))
                else:
                    ops.append(('suggest', rurl(3)))
            ops.append(('suggest', rng.choice(pool)[:rng.randint(1, 3)]))
            tests.append(fmt(ops))
    def big(n, npool, searchp):
        hosts = ['https://www.example.com/', 'https://docs.example.com/', 'http://shop.test.org/item/', 'https://a.io/']
        pool = []
        for _ in range(npool):
            u = rng.choice(hosts) + ''.join(rng.choice('abcdefghij0123456789/-_') for _ in range(rng.randint(1, 26)))
            pool.append(u[:50])
        ops = []
        for _ in range(n):
            if rng.random() < searchp:
                ops.append(('search', rng.choice(pool)))
            else:
                u = rng.choice(pool)
                ops.append(('suggest', u[:rng.randint(1, len(u))]))
        ops.append(('suggest', 'h'))
        return ops
    tests.append(fmt(big(3000, 300, 0.5)))
    tests.append(fmt(big(40000, 20000, 0.6)))
    tests.append(fmt(big(40000, 3000, 0.5)))
    # many distinct URLs searched, then many short-prefix queries
    ops = []
    pool = ['https://www.example.com/' + ''.join(rng.choice('abcdefghijklmnop') for _ in range(rng.randint(5, 26))) for _ in range(15000)]
    for u in pool:
        ops.append(('search', u))
    for _ in range(25000):
        ops.append(('suggest', 'https://www.example.com/' + rng.choice('abcdefghijklmnop')))
    tests.append(fmt(ops))
    return tests

